$ErrorActionPreference='Stop';$name='Forex Factory Five-Day Shadow Trial';$repo=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$runner=Join-Path $repo 'scripts\run_forex_factory_shadow_trial.ps1';$user=[Security.Principal.WindowsIdentity]::GetCurrent().Name
if(Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue){throw 'Exact task already exists'}
$action=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$runner`"";$trigger=New-ScheduledTaskTrigger -Once -At ((Get-Date).AddMinutes(1)) -RepetitionInterval(New-TimeSpan -Minutes 30) -RepetitionDuration(New-TimeSpan -Days 7);$settings=New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -ExecutionTimeLimit(New-TimeSpan -Minutes 2);$principal=New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
Register-ScheduledTask -TaskName $name -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Description 'Five-active-day observation-only Forex Factory context trial. No order influence or trading authority.'|Out-Null
